class PersonGateway {
  static async find(pool, id) {
    const { rows } = await pool.query(
      'SELECT id, last_name, deps FROM people WHERE id = $1', [id]);
    return rows[0] ? new PersonGateway(rows[0].id, rows[0].last_name, rows[0].deps) : null;
  }
  constructor(id, lastName, deps) { this.id = id; this.lastName = lastName; this.deps = deps; }
  async update(pool) {
    await pool.query('UPDATE people SET last_name = $2, deps = $3 WHERE id = $1',
                     [this.id, this.lastName, this.deps]);
  }
}
